using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Saldo360.Domain.Debts;using Saldo360.Domain.Workspaces;using Saldo360.Domain.Planning;
namespace Saldo360.Infrastructure.Persistence.Configurations;
internal sealed class FinancialDebtInstallmentReconciliationConfiguration:IEntityTypeConfiguration<FinancialDebtInstallmentReconciliation>{public void Configure(EntityTypeBuilder<FinancialDebtInstallmentReconciliation>b){b.ToTable("financial_debt_installment_reconciliations");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.HasIndex(x=>new{x.WorkspaceId,x.DebtInstallmentId}).IsUnique().HasFilter("removed_at IS NULL");b.HasIndex(x=>new{x.WorkspaceId,x.PlannedTransactionId}).IsUnique().HasFilter("removed_at IS NULL");b.HasOne<FinancialWorkspace>().WithMany().HasForeignKey(x=>x.WorkspaceId).OnDelete(DeleteBehavior.Restrict);b.HasOne<FinancialDebtInstallment>().WithMany().HasForeignKey(x=>new{x.WorkspaceId,x.DebtInstallmentId}).HasPrincipalKey(x=>new{x.WorkspaceId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<FinancialPlannedTransaction>().WithMany().HasForeignKey(x=>new{x.WorkspaceId,x.PlannedTransactionId}).HasPrincipalKey(x=>new{x.WorkspaceId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
